import { cacheLife } from 'next/cache'

// Shared project totals are reusable across requests: cache the result with
// `use cache` and a `minutes` lifetime so every member reads the same totals
// without re-running the (simulated) data fetch on each request.
export async function getProjectTotals() {
  'use cache'
  cacheLife('minutes')
  await new Promise((resolve) => setTimeout(resolve, 120))
  return { active: 12, archived: 4 }
}

