import { Suspense } from 'react'
import { cookies, headers } from 'next/headers'
import { getProjectTotals } from '@/lib/projects'

export default function DashboardPage() {
  return (
    <main>
      {/* Static shell: the heading and the reusable, cached shared totals
          prerender and load instantly for everyone. */}
      <h1>Workspace</h1>
      <ProjectTotals />

      {/* Request-specific content: name, team, and region are read from
          cookies/headers at request time, so they stream in behind a
          <Suspense> boundary. The frame below stays visible while it loads. */}
      <Suspense fallback={<MemberFrameSkeleton />}>
        <MemberDetails />
      </Suspense>
    </main>
  )
}

async function ProjectTotals() {
  'use cache'
  const totals = await getProjectTotals()
  return (
    <section>
      <p>{totals.active} active projects</p>
      <p>{totals.archived} archived projects</p>
    </section>
  )
}

async function MemberDetails() {
  const cookieStore = await cookies()
  const requestHeaders = await headers()
  const member = cookieStore.get('member')?.value ?? 'Guest'
  const team = cookieStore.get('team')?.value ?? 'Community'
  const region = requestHeaders.get('x-region') ?? 'global'
  return (
    <section>
      <p>Welcome, {member}</p>
      <p>Team: {team}</p>
      <p>Region: {region}</p>
    </section>
  )
}

function MemberFrameSkeleton() {
  return (
    <section aria-busy="true">
      <p>Welcome, …</p>
      <p>Team: …</p>
      <p>Region: …</p>
    </section>
  )
}

